def systemic_risk(negative_frac, dispersion):
    dispersion_norm = (dispersion - 0.007)/(0.028-0.007)
    return negative_frac * (1 - dispersion_norm)

def asset_count_adjusted_diversification(n_assets, corr):
    corr_clipped = clip(corr, 0.2, 0.6)
    return n_assets / (1 + corr_clipped * 50)

def skewness_proxy(mean_return, negative_frac):
    mean_return_norm = (mean_return - (-0.005))/(0.005 - (-0.005))
    negative_frac_norm = (negative_frac - 0.3)/(0.6 - 0.3)
    return mean_return_norm / (negative_frac_norm + 1e-6)

def data_quality_volatility(volatility, missing):
    missing_clipped = clip(missing, 0.0, 0.3)
    return volatility * (1 - missing_clipped)

def dispersion_volatility_ratio(dispersion, volatility):
    dispersion_norm = (dispersion - 0.007)/(0.028-0.007)
    return dispersion_norm / volatility

def negative_return_concentration(frac, n_assets):
    n_assets_norm = (n_assets - 4)/(59 - 4)
    return frac / n_assets_norm

def cross_sectional_skewness(mean_return, negative_frac, n_assets):
    mean_return_norm = (mean_return - (-0.005))/(0.005 - (-0.005))
    return (mean_return_norm + 0.001) / (negative_frac * n_assets)
